  "claims": [
    {
      "claim": "Posaconazole, a large lipophilic azole with solubility-limited absorption, had human absolute oral bioavailability of 42–56% in fasted and 85–87% in fed states; all exceed the 20% threshold. L2 low values in cats (15.9%) and fasted variability are species/formulation-specific and do not override human data.",
      "card_ids": ["C02", "C03", "C09", "C13", "C24", "C31", "C32"]
    },
    {
      "claim": "UDCA, a steroid carboxylic acid structurally closest to the query's steroid-acid core, had systemic availability of 78–87% after oral dosing in cirrhotic patients.",
      "card_ids": ["C18"]
    },
    {
      "claim": "BI 425809, a challenging lipophilic oral drug, had absolute F of 71.64% (90% CI 64.3–79.9) in fasted healthy subjects; L2 duplicates confirm the same value.",
      "card_ids": ["C01", "C04", "C15", "C21", "C29", "C35"]
    },
    {
      "claim": "Cilomilast, an acid-containing oral drug, had mean absolute F of 96% (solution) and 103% (tablet) in fasted subjects.",
      "card_ids": ["C12", "C28"]
    },
    {
      "claim": "KNI-272, a large peptidomimetic, had absolute F of 36.4% as a post-prandial capsule; L2 shows formulation/dose dependence (15.7% syrup, 22.1% capsule at 4 mg/kg), but the capsule values at relevant doses are at/above 20%.",
      "card_ids": ["C05", "C23", "C33"]
    },
    {
      "claim": "Other human L1 F values in visible contexts are above 20%: perindopril 66–95%, atazanavir >90%, pentazocine ~0.68–0.70 in cirrhosis, and phenoxymethylpenicillin 35.9–82.6% in children; L2 pig penicillin V low F is species-specific.",
      "card_ids": ["C19", "C11", "C20", "C07", "C16", "C06", "C08", "C14", "C17", "C22", "C27", "C26", "C30"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C22", "C23", "C24", "C25", "C26", "C27", "C28", "C29", "C30", "C31", "C32", "C33", "C34", "C35"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "No prandial state is specified for the query; fed/fasted can substantially change F, as seen with posaconazole.",
    "No formulation, IV-comparator, or human PK data are available for the query itself.",
    "Physicochemical liabilities (MW 730, logP 8.62, TPSA 125, zwitterionic character) may limit absorption, but no affirmative low-F experimental evidence is present.",
    "Transfer from visible contexts is qualitative; no exact structural match is available."
  ],
  "decision_summary": "The better-supported prediction remains high: all transferable human L1 records report F above 20%, including structurally relevant steroid-acid (UDCA 78–87%) and large azole (posaconazole 42–87%) contexts. New L2 low-F values are species- or formulation-specific (pig penicillin V, cat posaconazole suspension, KNI-272 syrup) and do not provide affirmative transferable evidence for F<20% in the query. Physicochemical liabilities remain an uncertain prior, not endpoint proof."
}

